using Cortex.Core.Flows;
namespace Cortex.Video.Editing;
public static class EditorialDecisionV2Validation {
    public static IReadOnlyList<FlowIssue> Validate(EditorialDecisionPlanDocument plan) {
        var issues=new List<FlowIssue>();void Error(string path,string text)=>issues.Add(new("edit.decisions.v2",path,text));if(plan.Schema!=EditingDocumentKinds.DecisionsV2) {if(plan.Catalog!=null || plan.Scenes.Any(scene=>scene.Proposal.Editing!=null))Error("/schema","Advanced composition fields require decisions v2.");return issues;}
        if(plan.Catalog is null || plan.Catalog.Schema!="helengine.media.capabilities.v1" || !EditingContractValidator.Hash(plan.Catalog.Fingerprint))Error("/catalog","V2 requires an explicit pinned engine catalog.");
        foreach(var scene in plan.Scenes) {var edit=scene.Proposal.Editing;if(edit is null)continue;string path="/scenes/"+scene.BeatId;if(!double.IsFinite(edit.VoiceGain) || edit.VoiceGain is <0 or >16 || edit.VoiceEnvelopes.Any(envelope=>envelope.Type is not("linear" or "equal_power_in" or "equal_power_out") || !double.IsFinite(envelope.StartSec+envelope.DurationSec+envelope.From+envelope.To) || envelope.StartSec<0 || envelope.DurationSec<=0 || envelope.StartSec+envelope.DurationSec>scene.Proposal.DurationSec || envelope.From is <0 or >16 || envelope.To is <0 or >16))Error(path,"Invalid voice gain or envelope.");if(edit.Animations.Count>32 || edit.Effects.Count>16 || edit.Audio.Count>32)Error(path,"Composition request exceeds limits.");
            foreach(var animation in edit.Animations) {if(animation.Keyframes.Count is <1 or >128 || animation.Keyframes.Any(frame=>!double.IsFinite(frame.TimeSec) || !double.IsFinite(frame.Value) || frame.TimeSec<0 || frame.TimeSec>scene.Proposal.DurationSec) || animation.Keyframes.Zip(animation.Keyframes.Skip(1)).Any(pair=>pair.First.TimeSec>=pair.Second.TimeSec))Error(path,"Invalid keyframe timing.");}
            if(edit.Transition is {} transition && (!double.IsFinite(transition.DurationSec) || transition.DurationSec<=0 || transition.DurationSec>scene.Proposal.DurationSec || !double.IsFinite(transition.AudioFadeSec) || transition.AudioFadeSec<0 || transition.AudioFadeSec>2))Error(path,"Invalid explicit transition overlap.");
            foreach(var audio in edit.Audio) {if(string.IsNullOrWhiteSpace(audio.MediaId) || !double.IsFinite(audio.StartSec+audio.DurationSec+audio.SourceInSec+audio.Gain) || audio.StartSec<0 || audio.DurationSec<=0 || audio.StartSec+audio.DurationSec>scene.Proposal.DurationSec || audio.SourceInSec<0 || audio.Gain is <0 or >16 || audio.Envelopes.Any(envelope=>envelope.Type is not("linear" or "equal_power_in" or "equal_power_out") || !double.IsFinite(envelope.StartSec+envelope.DurationSec+envelope.From+envelope.To) || envelope.StartSec<0 || envelope.DurationSec<=0 || envelope.StartSec+envelope.DurationSec>audio.DurationSec || envelope.From is <0 or >16 || envelope.To is <0 or >16))Error(path,"Invalid audio interval or gain envelope.");}
        }return issues;
    }
}
